{"path": "tree_building.py", "content": "class Record:
    def __init__(self, record_id, parent_id):
        self.record_id = record_id
        self.parent_id = parent_id


class Node:
    def __init__(self, node_id):
        self.node_id = node_id
        self.children = []


def BuildTree(records):
    """Build a tree from unsorted records and return its root Node (or None)."""
    if not records:
        return None

    ordered = sorted(records, key=lambda record: record.record_id)
    nodes = {}

    for index, record in enumerate(ordered):
        if record.record_id != index:
            raise ValueError('Record id is invalid or out of order.')
        if record.parent_id > record.record_id:
            raise ValueError("Node parent_id should be smaller than it's record_id.")
        if record.parent_id == record.record_id and record.record_id != 0:
            raise ValueError('Only root should have equal record and parent id.')

        node = Node(record.record_id)
        nodes[record.record_id] = node
        if record.record_id != 0:
            # Parents always have lower ids, so they already exist; children
            # are appended in ascending id order.
            nodes[record.parent_id].children.append(node)

    return nodes[0]
"}

